head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil20700";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — lang

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil20700.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_12", fn: function(){ return ((dma_pageContext.get("lang") ?? "")==='en'); } }, { id: "c_otherwise_17", fn: function(){ return (!(((dma_pageContext.get("lang") ?? "")==='en'))); } }, { id: "txt_b32", fn: function(){ return ((dma_pageContext.get("lang") ?? "")==='en'); } }, { id: "c_otherwise_33", fn: function(){ return (!(((dma_pageContext.get("lang") ?? "")==='en'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return " " + String(String((dma_pageContext.get("retHTML") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name td_13_onclick
 * @description td_13 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.td_13_onclick = function(e){
    try {
        scwin.goUrl(11)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil20700.td_13_onclick' }); }
};

/**
 * @method
 * @name td_20_onclick
 * @description td_20 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.td_20_onclick = function(e){
    try {
        scwin.goUrl(12)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil20700.td_20_onclick' }); }
};

/**
 * @method
 * @name img_36_onclick
 * @description img_36 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_36_onclick = function(e){
    try {
        scwin.download(1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil20700.img_36_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goUrl
 * @description go Url 처리
 * @param {String} _flag _flag
 * @returns {void}
 * @hidden N
 */
scwin.goUrl = function (_flag) {
    if (_flag === 11) {
        self.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil20100/jldfil20100.xml', { method: "searchBalanceSheet", lang: "ko" });
    } else {
        if (_flag === 12) {
            self.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil20100/jldfil20100.xml', { method: "searchBalanceSheet", lang: "en" });
        } else {
            if (_flag === 21) {
                self.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil20100/jldfil20100.xml', { method: "searchCashFlowTable", lang: "ko" });
            } else {
                if (_flag === 22) {
                    self.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil20100/jldfil20100.xml', { method: "searchCashFlowTable", lang: "en" });
                } else {
                    if (_flag === 31) {
                        self.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil20100/jldfil20100.xml', { method: "searchIncomeStatement", lang: "ko" });
                    } else {
                        if (_flag === 32) {
                            self.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil20100/jldfil20100.xml', { method: "searchIncomeStatement", lang: "en" });
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name download
 * @description download 처리
 * @param {String} _flag _flag
 * @returns {void}
 * @hidden N
 */
scwin.download = function (_flag) {
    if (_flag === 1) {
        self.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil20100/jldfil20100.xml', { method: "downloadBalanceSheet", lang: (String(((dma_pageContext.get("lang") ?? "")) === null ? '' : ((dma_pageContext.get("lang") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("lang") ?? "")) === null ? '' : ((dma_pageContext.get("lang") ?? "")))) });
    } else {
        if (_flag === 2) {
            self.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil20100/jldfil20100.xml', { method: "downloadCashFlowTable", lang: (String(((dma_pageContext.get("lang") ?? "")) === null ? '' : ((dma_pageContext.get("lang") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("lang") ?? "")) === null ? '' : ((dma_pageContext.get("lang") ?? "")))) });
        } else {
            if (_flag === 3) {
                self.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil20100/jldfil20100.xml', { method: "downloadIncomeStatement", lang: (String(((dma_pageContext.get("lang") ?? "")) === null ? '' : ((dma_pageContext.get("lang") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("lang") ?? "")) === null ? '' : ((dma_pageContext.get("lang") ?? "")))) });
            }
        }
    }
};
